SELECT cc.cc_division, d_open.d_year AS open_year, COUNT(*) AS num_call_centers, SUM(cc.cc_sq_ft) AS total_sq_ft, AVG(cc.cc_tax_percentage) AS avg_tax_pct, SUM(date_diff('day', d_open.d_date, d_close.d_date)) AS total_days_open, RANK() OVER (PARTITION BY d_open.d_year ORDER BY SUM(cc.cc_employees) DESC) AS employee_rank FROM call_center cc JOIN date_dim d_open ON cc.cc_open_date_sk = d_open.d_date_sk JOIN date_dim d_close ON cc.cc_closed_date_sk = d_close.d_date_sk WHERE cc.cc_class = 'large' AND d_open.d_year BETWEEN 2000 AND 2005 AND cc.cc_employees IS NOT NULL GROUP BY cc.cc_division, d_open.d_year HAVING COUNT(*) > 1 ORDER BY total_sq_ft DESC, employee_rank LIMIT 100
